INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `status`, `featured_image_id`, `excerpt`, `created_by`, `updated_by`, `published_at`, `created_at`, `updated_at`, `deleted_at`, `content`, `meta_title`, `meta_description`, `subtitle`) VALUES ('2', 'About GoldMatrix', 'about', 'about', 'published', NULL, NULL, NULL, NULL, NULL, '2026-08-30 18:58:24', '2026-08-30 18:58:24', NULL, 'GoldMatrix ERP is the definitive cloud jewellery ERP software crafted exclusively for modern jewellery retailers, wholesalers, bullion dealers, and manufacturers across the UAE and India.', 'About GoldMatrix | Enterprise Jewellery ERP Software Leaders', 'Discover GoldMatrix ERP — empowering 1,200+ jewellery enterprises with dual headquarters in Sharjah Central Gold Souq & India.', 'Pioneering Gold & Jewellery Management Software Across UAE & India Since 2011.');
