INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `status`, `featured_image_id`, `excerpt`, `created_by`, `updated_by`, `published_at`, `created_at`, `updated_at`, `deleted_at`, `content`, `meta_title`, `meta_description`, `subtitle`) VALUES ('4', 'Solutions & Services', 'services', 'services', 'published', NULL, NULL, NULL, NULL, NULL, '2026-08-30 18:58:24', '2026-08-30 18:58:24', NULL, 'Explore specialized jewellery software solutions tailored for every segment of the jewelry and precious metals industry.', 'Jewellery ERP Solutions & Modules | GoldMatrix', 'Specialized jewelry software modules for Retail POS, Wholesale, Bullion Trading, and Workshop Manufacturing.', 'End-to-end Enterprise Solutions tailored for Retail, Wholesale, Bullion, and Manufacturing.');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `status`, `featured_image_id`, `excerpt`, `created_by`, `updated_by`, `published_at`, `created_at`, `updated_at`, `deleted_at`, `content`, `meta_title`, `meta_description`, `subtitle`) VALUES ('5', 'Why Choose GoldMatrix', 'why-us', 'default', 'published', NULL, NULL, NULL, NULL, NULL, '2026-08-30 18:58:24', '2026-09-08 09:52:35', NULL, 'GoldMatrix is built ground-up for the jewelry industry with native support for dual-metal accounting, automatic making charge calculations, and certified weighing scale integrations.', 'Why GoldMatrix ERP | Built Exclusively for Jewellery Businesses', 'Learn why leading jewelry brands choose GoldMatrix over generic ERPs.', 'Why over 1,200+ top jewelry businesses trust GoldMatrix ERP for their daily operations.');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `status`, `featured_image_id`, `excerpt`, `created_by`, `updated_by`, `published_at`, `created_at`, `updated_at`, `deleted_at`, `content`, `meta_title`, `meta_description`, `subtitle`) VALUES ('6', 'Customer Reviews & Case Studies', 'testimonials', 'default', 'published', NULL, NULL, NULL, NULL, NULL, '2026-08-30 18:58:24', '2026-08-30 18:58:24', NULL, 'Real stories from jewelry retail chains and manufacturers who modernized their operations with GoldMatrix ERP.', 'Customer Reviews & Stories | GoldMatrix Jewellery ERP', 'Read verified reviews and client testimonials from jewelry owners across UAE and India.', 'See how jewelers scaled their business and reduced inventory leakage with GoldMatrix.');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('1', 'Dashboards & Live Rates', 'dashboard-live-rates', NULL, NULL, 'bi-speedometer2', NULL, NULL, 'published', '1', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'MULTI-ROLE INTELLIGENCE', 'Executive & Operational Dashboards', 'Role-Based Dashboards & Live Gold Rate System for Jewellery Businesses', 'One Screen. Every Branch. Real-Time Retail, Wholesale, Manufacturing, Sales & Stock Intelligence.', 'Role-Based Dashboards & Live Gold Rate System for Jewellery Businesses', 'One Screen. Every Branch. Real-Time Retail, Wholesale, Manufacturing, Sales & Stock Intelligence.', 'Generic ERP software gives everyone the same cluttered screen — but a retail showroom manager needs completely different metrics than a factory production supervisor, a bullion wholesaler, or a floor salesperson. GoldMatrix provides 6 dedicated role-based and operational dashboards: Retailer, Wholesaler, Manufacturing / Job Worker, Sales Person, Live Gold Rates, and Real-Time Stock. Each dashboard surfaces the exact numbers, live tickers, jobwork queues, and inventory alerts relevant to that role, while syncing live 24K, 22K, 18K, 14K gold and 925 silver market rates across all branch locations.', 'Dedicated role dashboards for Retailers, Wholesalers, Manufacturers, Sales Teams, Live Gold Rates, and Multi-Branch Stock balances.', '[\"Retailer, Wholesaler, Manufacturing & Sales Person Role Dashboards\",\"Live Gold & Silver Rates Dashboard (24K\\/22K\\/18K\\/14K\\/925) with Multi-Branch Sync\",\"Stock Dashboard with Real-Time Vault Balances & Reorder Alerts\",\"Date-Based Business Snapshot & Real-Time Multi-Store Analytics\"]', 'Jewellery Retailers, Wholesalers, Manufacturers, Sales Teams & Showroom Owners', 'Built for multi-branch jewellery retailers, high-volume wholesalers, manufacturing units, and showroom sales teams who need role-specific operational dashboards and up-to-the-second gold price synchronization.', '[{\"icon\":\"bi-shop\",\"title\":\"Retailer Dashboard\",\"desc\":\"Real-time showroom command center tracking counter sales, footfall conversion, top-selling design categories, customer receivables, and daily cash, card, and UPI collections.\",\"points\":[\"Live counter billing metrics & daily collection\",\"Top-selling ornament categories & fast movers\",\"Customer outstanding & credit balance alerts\",\"Showroom sales target vs achievement gauge\"]},{\"icon\":\"bi-truck\",\"title\":\"Wholesaler Dashboard\",\"desc\":\"Engineered for high-volume wholesale operations, tracking B2B party outstandings, bulk order dispatches, credit limits, and unhedged bullion exposures.\",\"points\":[\"B2B party balance & credit limit alerts\",\"Bulk order dispatch pipeline tracking\",\"Bullion fixing contracts & exposure ledger\",\"Wholesale gross margin & volume analytics\"]},{\"icon\":\"bi-tools\",\"title\":\"Manufacturing \\/ Job Worker Dashboard\",\"desc\":\"Workshop floor monitor tracking active jobcards, station WIP (Melting, Casting, Setting, Polishing), Karigar queue delays, and daily metal loss tolerances.\",\"points\":[\"Stage-by-stage workshop WIP monitoring\",\"Karigar queue & turnaround time tracking\",\"Live metal loss & permissible ghat variance flags\",\"Daily finished piece handover log\"]},{\"icon\":\"bi-person-badge\",\"title\":\"Sales Person Dashboard\",\"desc\":\"Empower floor staff with individual daily sales targets, customer commission earnings on making charges, assigned showcase tray custody, and incentive leaderboards.\",\"points\":[\"Personal sales vs target achievement dial\",\"Commission & incentive calculation on making charges\",\"Assigned showcase tray custody check-in\\/out\",\"Showroom floor performance leaderboard\"]},{\"icon\":\"bi-graph-up-arrow\",\"title\":\"Gold Rates Dashboard (Live Ticker)\",\"desc\":\"Automated live rate board syncing 24K, 22K, 18K, 14K gold and 925 silver market feeds directly to POS billing counters and customer-facing digital TV displays.\",\"points\":[\"Continuous live market price feed\",\"Showroom TV digital board output\",\"Custom margin\\/markup per branch location\",\"Zero manual entry pricing errors\"]},{\"icon\":\"bi-boxes\",\"title\":\"Stock Dashboard\",\"desc\":\"Instant 360° inventory overview showing total showroom stock, pure bullion vault weight, in-transit branch transfers, approval memos, and reorder alerts.\",\"points\":[\"Total gross & net weight in vaults and counters\",\"Memo In \\/ Memo Out balance tracking\",\"Low-stock reorder alerts per showcase tray\",\"Multi-branch stock distribution map\"]}]', 'Multi-Role Dashboards: Role Selection & Live Gold Rate Ticker', 'Interface showcasing the 6 specialized dashboards (Retailer, Wholesaler, Manufacturing/Jobworker, Salesperson, Gold Rates, Stock) alongside the live multi-karat rate ticker and branch summary tiles.', '[\"Switch between Retailer, Wholesaler, Manufacturing, and Salesperson views\",\"Live rate numbers updating in real time (24K\\/22K\\/18K\\/14K and 925 Silver)\",\"Multi-branch stock and sales summary tiles updating live from one login\"]', 'https://goldmatrixsoftware.com/wp-content/uploads/2026/02/imgi_53_erp-mockup01.png', '[{\"q\":\"How do role-based dashboards benefit different teams in a jewellery enterprise?\",\"a\":\"Showroom owners see top-line group profits; retail managers see counter collections; workshop supervisors track Karigar jobs; and sales staff monitor their personal commissions — all from custom, permission-controlled screens.\"},{\"q\":\"How often does the Gold Rates dashboard update market prices?\",\"a\":\"The rate engine continuously syncs 24K, 22K, 18K, 14K gold and 925 silver market prices, instantly broadcasting them to connected POS billing counters and digital showroom display boards.\"},{\"q\":\"Can each branch apply different margins on the shared Gold Rates feed?\",\"a\":\"Yes. Centralized headquarters can manage the base market rate while allowing individual branches to configure location-specific markups or premiums.\"},{\"q\":\"What metrics does the Stock Dashboard highlight?\",\"a\":\"The Stock Dashboard gives real-time visibility into total pure metal weight, mounted diamond carats, items currently out on customer approval (Memo), and fast-depleting showcase trays.\"}]', '[\"business-opening\",\"operations\",\"stock-management\"]', 'Role-Based Dashboards & Live Gold Rate System for Jewellery Businesses | GoldMatrix ERP', 'Generic ERP software gives everyone the same cluttered screen — but a retail showroom manager needs completely different metrics than a factory production sup', 'dashboards & live rates, jewellery erp software, gold software, jewelry business system', '/features/dashboard-live-rates');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('2', 'Opening & Financial Ledgers', 'business-opening', NULL, NULL, 'bi-box-seam', NULL, NULL, 'published', '2', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'FINANCIAL & STOCK BASELINE', 'Opening & Core Ledgers', 'Jewellery Opening Stock, Account Ledgers & Metal Conversion Software', 'Accurate Product Opening, Dual Metal-Rupee Ledgers & Real-Time Bank Reconciliation.', 'Jewellery Opening Stock, Account Ledgers & Metal Conversion Software', 'Accurate Product Opening, Dual Metal-Rupee Ledgers & Real-Time Bank Reconciliation.', 'Starting your jewellery operations with 100% accurate stock and financial baselines is essential for error-free accounting. GoldMatrix\'s Opening module gives you complete control over your foundational data: record product opening with weight and purity specifications, maintain dual-balance account ledgers (gold grams + rupees) for customers, suppliers and Karigars, perform instant bidirectional Metal ↔ Amount conversions, and reconcile bank accounts seamlessly from day one.', 'Manage product opening, customer & supplier account ledgers, bidirectional metal-amount conversions, and multi-bank reconciliation.', '[\"Product Opening with weight, purity & cost recording\",\"Account Ledger with dual gold & rupee balances\",\"Metal to Amount & Amount to Metal dynamic conversion\",\"Bank Reconciliation for multiple linked accounts\"]', 'Jewellery Showroom Owners, Accountants, Bullion Dealers & Karigar Units', 'Ideal for jewellery business owners, showroom managers, and accountants who need metal and money tracked together as one unified financial baseline right from opening.', '[{\"icon\":\"bi-box-arrow-in-down\",\"title\":\"Product Opening\",\"desc\":\"Record opening stock and new product entries into your operational ledger with accurate cost, gross weight, net weight, and karat purity data captured at the point of entry.\",\"points\":[\"Capture gross, net & stone weight\",\"Purity and karat recording\",\"Cost and landing value entry\",\"Continuous & baseline product logging\"]},{\"icon\":\"bi-journal-bookmark-fill\",\"title\":\"Account Ledger\",\"desc\":\"Maintain complete customer, supplier, Karigar, and internal account ledgers with dual metal-weight and currency balances, fully searchable and exportable for audits or GST filing.\",\"points\":[\"Dual pure gold & currency balances\",\"Searchable transaction history\",\"Exportable for CA & GST filing\",\"Voucher-level transaction drill-down\"]},{\"icon\":\"bi-layers-fill\",\"title\":\"Metal to Amount Conversion\",\"desc\":\"Instantly convert gold or silver weight into monetary value using live market ticker rates or locked contract prices — essential for bullion purchases, old gold settlements, and scrap buybacks.\",\"points\":[\"Live market or fixed rate conversion\",\"Instant conversion voucher creation\",\"Essential for gold exchange & pledges\",\"Realized rate gain\\/loss tracking\"]},{\"icon\":\"bi-arrow-left-right\",\"title\":\"Amount to Metal Conversion\",\"desc\":\"Seamlessly convert cash deposits, customer advances, or booking amounts into equivalent pure gold or silver grams, protecting against future market price escalations.\",\"points\":[\"Convert cash advances into locked gold grams\",\"Rate-hedged customer bookings\",\"Accurate weight credit in customer ledger\",\"Zero calculation discrepancies\"]},{\"icon\":\"bi-bank2\",\"title\":\"Bank Reconciliation\",\"desc\":\"Match your internal accounting books against bank statements directly within the software, catching discrepancies, uncleared cheques, and card swipe settlements early.\",\"points\":[\"Multi-account bank statement matching\",\"Detect uncleared cheques & POS swipes\",\"Detailed reconciliation audit trail\",\"Zero month-end closing panic\"]}]', 'Product Opening, Metal ↔ Amount Calculator & Bank Reconciliation', 'Interface showcasing the Product Opening form, the live bidirectional Metal ↔ Amount conversion calculator, and the bank statement reconciliation screen with matched vs. unmatched transactions.', '[\"Product opening form capturing gross\\/net weight and purity\",\"Bidirectional Metal ↔ Amount calculator with real-time math\",\"Multi-account bank statement matching screen\"]', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"Is Product Opening a one-time entry or ongoing per new stock?\",\"a\":\"Product Opening is used both at initial onboarding to set starting stock and on an ongoing basis whenever new inventory batches enter your system with weight and purity details.\"},{\"q\":\"How does the Account Ledger track both metal weight and currency balances?\",\"a\":\"Every ledger account in GoldMatrix maintains dual columns — pure metal weight (grams\\/karat) and rupee amounts — ensuring complete balance integrity.\"},{\"q\":\"How does Metal to Amount and Amount to Metal conversion handle price fluctuations?\",\"a\":\"Conversions can be calculated against the live rate at the time of transaction or a fixed agreed rate, ensuring complete accuracy for advance bookings or scrap settlements.\"},{\"q\":\"Does Bank Reconciliation support multiple bank accounts?\",\"a\":\"Yes, the reconciliation module supports matching transactions across multiple linked bank accounts and payment gateways within the same dashboard.\"}]', '[\"dashboard-live-rates\",\"operations\",\"stock-management\"]', 'Jewellery Opening Stock, Account Ledgers & Metal Conversion Software | GoldMatrix ERP', 'Starting your jewellery operations with 100% accurate stock and financial baselines is essential for error-free accounting. GoldMatrix\'s Opening module gives yo', 'opening & financial ledgers, jewellery erp software, gold software, jewelry business system', '/features/business-opening');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('3', 'Operations (Finance Core)', 'operations', NULL, NULL, 'bi-currency-exchange', NULL, NULL, 'published', '3', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'FINANCE & BANKING CORE', 'Core Accounting', 'Jewellery Accounting & Metal Ledger Software — Operations Module', 'Track Money and Metal Together, Not in Two Separate Systems', 'Jewellery Accounting & Metal Ledger Software — Operations Module', 'Track Money and Metal Together, Not in Two Separate Systems', 'Jewellery accounting isn\'t just rupees and paise — it\'s gold grams, silver kilos, and constantly shifting metal value, all of which need to reconcile with your bank and cash position. Most accounting software treats jewellery businesses like any other retailer, forcing manual workarounds to track metal-to-money conversions. GoldMatrix\'s Operations module is built around this core reality: it manages product opening, account ledgers, metal-to-amount conversion, and bank reconciliation as one connected financial core, so your books balance in both currency and karat.', 'Manage product opening, account ledgers, metal-to-amount conversion, and bank reconciliation as one connected financial core.', '[\"Product Opening with cost, weight & purity entry\",\"Account Ledger for customers, suppliers & karigars\",\"Metal ↔ Amount dynamic rate conversion\",\"Direct Bank Reconciliation matching\"]', 'Jewellery Business Owners, Accountants & Bullion Traders', 'Built for jewellery business owners and accountants who need metal and money tracked as one system — particularly relevant for businesses handling gold exchange, pledge settlement, or bullion transactions where standard rupee-only accounting software falls short.', '[{\"icon\":\"bi-box-arrow-in-down\",\"title\":\"Product Opening\",\"desc\":\"Record new product entries into your operational ledger with accurate cost, weight, and purity data captured at the point of entry.\",\"points\":[\"Capture gross, net & stone weight\",\"Purity and karat recording\",\"Cost and landing value entry\",\"Continuous product logging\"]},{\"icon\":\"bi-journal-bookmark-fill\",\"title\":\"Account Ledger\",\"desc\":\"Maintain complete customer, supplier, and internal account ledgers with full transaction history, searchable and exportable for audits or GST filing.\",\"points\":[\"Dual pure gold & currency balances\",\"Searchable transaction history\",\"Exportable for CA & GST filing\",\"Voucher-level drill-down\"]},{\"icon\":\"bi-arrow-left-right\",\"title\":\"Metal to Amount \\/ Amount to Metal Conversion\",\"desc\":\"Instantly convert between gold\\/silver weight and monetary value using live or fixed rates — essential for pledge settlements, exchange transactions, and bullion trading where customers pay or receive in metal rather than cash.\",\"points\":[\"Live market or fixed rate conversion\",\"Instant conversion voucher creation\",\"Essential for gold exchange & pledges\",\"Realized rate gain\\/loss tracking\"]},{\"icon\":\"bi-bank2\",\"title\":\"Bank Reconciliation\",\"desc\":\"Match your books against bank statements directly within the system, catching discrepancies early instead of discovering them at month-end closing.\",\"points\":[\"Multi-account bank matching\",\"Detect uncleared cheques & swipes\",\"Reconciliation audit trail\",\"Zero month-end closing panic\"]}]', 'Metal ↔ Amount Calculator & Direct Bank Reconciliation', 'Split view showing the Metal ↔ Amount conversion calculator with live conversion examples, alongside the bank reconciliation screen with matched vs. unmatched transactions.', '[\"Live metal-to-currency conversion calculator with real-time math\",\"Bank statement reconciliation matching screen\",\"Seamless double-entry integrity between gold grams and liquid currency\"]', 'https://images.unsplash.com/photo-1586486855514-8c633cc6fd38?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"How does metal-to-amount conversion handle daily rate fluctuations?\",\"a\":\"Conversions can be calculated against the live rate at the time of transaction or a fixed rate you set, ensuring accuracy whether you\'re settling same-day or against a locked-in price.\"},{\"q\":\"Can the Account Ledger export data for GST filing or CA review?\",\"a\":\"Yes, ledger data is exportable in standard formats suitable for handoff to accountants or for GST return preparation.\"},{\"q\":\"Does bank reconciliation support multiple bank accounts?\",\"a\":\"Yes, the reconciliation module supports matching transactions across multiple linked bank accounts within the same operations dashboard.\"},{\"q\":\"Is Product Opening a one-time entry or ongoing per new stock?\",\"a\":\"Product Opening is used on an ongoing basis — every time new inventory enters your system, whether from purchase, manufacturing, or exchange, it\'s logged here with weight and purity captured at entry.\"}]', '[\"financial-statement\",\"order-management\",\"stock-management\"]', 'Jewellery Accounting & Metal Ledger Software — Operations Module | GoldMatrix ERP', 'Jewellery accounting isn\'t just rupees and paise — it\'s gold grams, silver kilos, and constantly shifting metal value, all of which need to reconcile with you', 'operations (finance core), jewellery erp software, gold software, jewelry business system', '/features/operations');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('4', 'Order Management', 'order-management', NULL, NULL, 'bi-cart-check', NULL, NULL, 'published', '4', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'SALES & ORDER PIPELINE', 'Order Lifecycle', 'Jewellery Order Management & Custom Manufacturing Work Order Software', 'From Custom Bridal Design & Repair to Factory Work Orders & Delivery', 'Jewellery Order Management & Custom Manufacturing Work Order Software', 'From Custom Bridal Design & Repair to Factory Work Orders & Delivery', 'Managing custom bridal jewellery, customer repairs, and wholesale production on paper slips leads to missed delivery dates, misplaced packets, and angry customers. GoldMatrix\'s Order Management module connects your sales counter directly to your workshop and outside vendors. Log custom sale orders with photos and advance receipts, track repair orders through every stage of fixing, generate manufacturing work orders for karigars, and manage outsourced vendor jobs — all with automated customer WhatsApp status updates.', 'Manage customer custom sale orders, repair jobs, manufacturing work orders, and outsourced vendor dispatch with automated milestone alerts.', '[\"Sale Order & Repair Order with photo & weight tracking\",\"Manufacturing Work Order & Karigar Jobcard creation\",\"Outsourced Manufacturing dispatch & return reconciliation\",\"Design Quotation CAD approval & Sales Register\"]', 'Custom Jewellery Designers, Bridal Showroom Desks & Wholesale Order Teams', 'Built for custom jewellery designers, bridal showroom order desks, repair centers, and wholesale coordinators who need total accountability over bespoke customer orders and strict delivery deadlines.', '[{\"icon\":\"bi-file-earmark-text\",\"title\":\"Sale Order\",\"desc\":\"Capture custom customer orders with design photos, target metal weight, diamond 4Cs specifications, delivery deadlines, and advance cash\\/old gold payments.\",\"points\":[\"Multi-photo design attachment\",\"Advance cash & old gold credit log\",\"Target delivery date scheduling\",\"WhatsApp confirmation with receipt\"]},{\"icon\":\"bi-tools\",\"title\":\"Repair Order\",\"desc\":\"Log customer repair jobs (resizing, stone replacement, soldering, rhodium) with received gross weight, photo verification, and digital repair barcodes.\",\"points\":[\"Received vs delivery weight audit\",\"Digital repair packet barcode\",\"Customer photo verification slip\",\"Ready for pickup WhatsApp alert\"]},{\"icon\":\"bi-arrow-repeat\",\"title\":\"Order & Repair Processing\",\"desc\":\"Move orders seamlessly through visual status stages (Design Approved > In Workshop > Setting > Polishing > Ready) with real-time bottleneck alerts.\",\"points\":[\"Visual stage progression\",\"Delayed order alerts\",\"Staff accountability tracking\",\"Live customer status look-up\"]},{\"icon\":\"bi-gear-wide-connected\",\"title\":\"Manufacturing Work Order\",\"desc\":\"Automatically convert approved customer sale orders into factory work orders with Bill of Materials (BOM), allocated pure gold, and assigned karigar units.\",\"points\":[\"Automated BOM generation\",\"Karigar work order printing\",\"Raw metal issue linkage\",\"Target delivery milestone control\"]},{\"icon\":\"bi-box-arrow-up-right\",\"title\":\"Outsourced Manufacturing\",\"desc\":\"Track orders sent to external specialized workshops (micro-pave diamond setting, laser engraving) with vendor challans and weight audit upon return.\",\"points\":[\"Outsourced vendor delivery notes\",\"Weight verification upon return\",\"Labor charge settlement voucher\",\"Third-party status tracking\"]},{\"icon\":\"bi-gem\",\"title\":\"Design Quotation\",\"desc\":\"Create high-converting 3D CAD design quotations with live metal rate estimates, making charge calculations, and shareable WhatsApp PDF links.\",\"points\":[\"Live rate price estimation\",\"3D CAD rendering attachments\",\"Instant 1-click customer approval\",\"Convert quotation to order seamlessly\"]},{\"icon\":\"bi-table\",\"title\":\"Sales Register\",\"desc\":\"Comprehensive searchable register tracking every customer order, delivery challan, pending balance, and sales executive attribution.\",\"points\":[\"Search by customer or design code\",\"Sales executive commission log\",\"Pending delivery countdown\",\"Complete audit history\"]}]', 'Order Pipeline & Manufacturing Work Order Workflow', 'Visual representation of custom bridal orders moving from initial customer CAD quotation to factory work orders, outsourced vendor tracking, and final delivery.', '[\"Live status progression from quotation to manufacturing work order\",\"Repair packet barcode tracking with received vs delivered weight\",\"Automated customer WhatsApp status update dispatch\"]', 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"Can customers receive automated WhatsApp updates when their order status changes?\",\"a\":\"Yes. When an order moves to \\\"In Production\\\" or \\\"Ready for Pickup\\\", GoldMatrix sends automated WhatsApp notifications to the customer.\"},{\"q\":\"How are customer advance payments in cash or old gold adjusted at final billing?\",\"a\":\"Advance cash, card deposits, and old gold exchange credits are linked to the Order ID and automatically deducted from the final GST tax invoice.\"},{\"q\":\"Does it generate printable jobcards with barcodes for workshop karigars?\",\"a\":\"Yes. Work orders print complete jobcards containing reference photos, metal weight, stone counts, and barcodes for quick workshop scanning.\"},{\"q\":\"Can we track orders sent to outside third-party manufacturers?\",\"a\":\"Yes. The Outsourced Manufacturing module generates external vendor challans, tracks transit status, and reconciles return weight before final assembly.\"}]', '[\"production\",\"stock-management\",\"operations\"]', 'Jewellery Order Management & Custom Manufacturing Work Order Software | GoldMatrix ERP', 'Managing custom bridal jewellery, customer repairs, and wholesale production on paper slips leads to missed delivery dates, misplaced packets, and angry custome', 'order management, jewellery erp software, gold software, jewelry business system', '/features/order-management');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('5', 'Production', 'production', NULL, NULL, 'bi-tools', NULL, NULL, 'published', '5', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'PROPRIETARY WORKSHOP USP', 'Manufacturing & Jobwork', 'Jewellery Manufacturing, Karigar Jobwork & Metal Loss Tracking Software', 'Milligram-Precision Control Across Every Insource, Outsource & Workshop Process', 'Jewellery Manufacturing, Karigar Jobwork & Metal Loss Tracking Software', 'Milligram-Precision Control Across Every Insource, Outsource & Workshop Process', 'Uncontrolled metal loss and delayed karigar jobwork destroy jewellery manufacturing profit margins. GoldMatrix\'s Production module is purpose-built for jewellery workshops and factory floors. Manage department-wise workflows (Melting, Casting, Filing, Setting, Polishing, Rhodium), track real-time jobwork queues, generate barcode jobcards, audit allowable vs. actual metal loss, and print daily manufacturing summaries with 0.001g accuracy.', 'Full-cycle jewellery manufacturing software tracking WIP departments, karigar jobwork queues, metal loss, and daily closing summaries.', '[\"Department-wise Insource & Outsource reports\",\"Jobwork Queue + Real-time Queue Report\",\"Loss Tracking & Daily Manufacturing Closing Report\",\"Worklog, Jobcard Report & Barcode Jobcard Print\"]', 'Jewellery Manufacturers, Karigar Workshops & Factory Production Heads', 'Built for fine jewellery manufacturers, casting houses, karigar workshops, and factory production directors who need to eliminate unaccounted metal leakage and streamline jobwork delivery.', '[{\"icon\":\"bi-diagram-3-fill\",\"title\":\"Department\",\"desc\":\"Configure specialized workshop departments (Melting, Casting, Filing, Diamond Setting, Polishing, Rhodium, Hallmarking) with custom stage sequences.\",\"points\":[\"Multi-stage department routing\",\"Stage-wise WIP inventory balance\",\"Department capacity scheduling\",\"Operator station mapping\"]},{\"icon\":\"bi-person-workspace\",\"title\":\"Insource Department Report\",\"desc\":\"Track production volume, fine gold issued, scrap returned, and cycle times across all internal workshop departments with operator efficiency KPIs.\",\"points\":[\"Internal station productivity\",\"Stage-by-stage metal weight ledger\",\"Scrap recovery tracking\",\"WIP inventory valuation\"]},{\"icon\":\"bi-share-fill\",\"title\":\"Outsource Department Report\",\"desc\":\"Monitor metal issued to external jobworkers and outside casting units with transit tracking, delivery challans, and return weight audits.\",\"points\":[\"Outside contractor metal balance\",\"External jobwork challans\",\"Return weight reconciliation\",\"Labor charge settlement\"]},{\"icon\":\"bi-list-task\",\"title\":\"Jobwork Queue & Queue Report\",\"desc\":\"Live visual queue of all pending, in-progress, and completed jobcards across workshops with express order prioritization flags.\",\"points\":[\"Live factory floor queue\",\"Express order prioritization\",\"Karigar workload allocation\",\"Real-time bottleneck alerts\"]},{\"icon\":\"bi-gear\",\"title\":\"Manufacturing Process\",\"desc\":\"Define standard process parameters, allowable wastage percentages, labor charge rates (per gram or per piece), and target turnaround hours.\",\"points\":[\"Process-wise wastage standards\",\"Labor calculation formulas\",\"Standard operating workflows\",\"Quality check checkpoints\"]},{\"icon\":\"bi-exclamation-triangle-fill\",\"title\":\"Loss Tracking & Closing Report\",\"desc\":\"Calculate actual vs allowable metal loss per karigar and process. Generate daily closing reports showing total metal balance and scrap recovery.\",\"points\":[\"Milligram-precision loss calculation\",\"Allowable vs actual variance flags\",\"Karigar loss liability recovery\",\"Daily factory closing balance sheet\"]},{\"icon\":\"bi-clock-history\",\"title\":\"Worklog Report\",\"desc\":\"Maintain timestamped audit logs of worker clock-ins, jobcard station handovers, labor time spent, and process completions.\",\"points\":[\"Worker station timestamps\",\"Time spent per manufacturing stage\",\"Operator productivity log\",\"Audit-ready job history\"]},{\"icon\":\"bi-qr-code-scan\",\"title\":\"Jobcard Report & Jobcard Print\",\"desc\":\"Generate detailed jobcard summaries and print durable barcode tags with design photos, metal specs, and stone requirements for quick scanning.\",\"points\":[\"Barcode & QR jobcard printouts\",\"Design photo attachment\",\"Required gold & stone specifications\",\"Direct finished stock tag conversion\"]},{\"icon\":\"bi-pie-chart-fill\",\"title\":\"Daily Manufacturing Summary\",\"desc\":\"Executive daily summary showing total metal melted, fine gold issued, finished pieces produced, total scrap recovered, and labor accrued.\",\"points\":[\"Daily production yield efficiency\",\"Metal balance reconciliation\",\"Total labor cost accrued\",\"Finished goods transferred to retail stock\"]}]', 'Factory Floor Control: Jobwork Queue & Metal Loss Tracking', 'Visual representation of the live Jobwork Queue dashboard showing stage progression alongside the Metal Loss Tracking audit report.', '[\"Live jobwork queue with department-wise WIP status\",\"Milligram-precision loss tracking comparing issued gold vs finished pieces\",\"1-Click barcode jobcard printing for station scanning\"]', 'https://goldmatrixsoftware.com/wp-content/uploads/2026/02/imgi_53_erp-mockup01.png', '[{\"q\":\"How does GoldMatrix calculate karigar metal loss and wastage allowance?\",\"a\":\"GoldMatrix compares pure metal issued against finished product weight plus recovered scrap, evaluating the variance against your pre-configured allowable wastage limits.\"},{\"q\":\"Can workers update job progress using barcode scanners on the shop floor?\",\"a\":\"Yes. Workers scan the barcode on their printed jobcard at each workstation kiosk to log start and completion timestamps in real time.\"},{\"q\":\"Does it handle both in-house factory staff and independent outside karigars?\",\"a\":\"Yes. You can track internal employee worklogs as well as external contractor metal ledgers, labor bills, and tax deduction vouchers.\"},{\"q\":\"Can finished manufactured goods be directly converted into barcode-tagged retail inventory?\",\"a\":\"Yes. One click transfers completed production batches into tagged stock ready for showroom billing.\"}]', '[\"order-management\",\"stock-management\",\"financial-statement\"]', 'Jewellery Manufacturing, Karigar Jobwork & Metal Loss Tracking Software | GoldMatrix ERP', 'Uncontrolled metal loss and delayed karigar jobwork destroy jewellery manufacturing profit margins. GoldMatrix\'s Production module is purpose-built for jeweller', 'production, jewellery erp software, gold software, jewelry business system', '/features/production');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('6', 'Financial Statement', 'financial-statement', NULL, NULL, 'bi-receipt-cutoff', NULL, NULL, 'published', '6', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'COMPLIANCE & AUDIT', 'Financial Reporting', 'Jewellery Accounting, Trial Balance & GST Financial Statement Software', 'Live Balance Sheets, Metal-Aware P&L & 100% Tax-Compliant Reporting', 'Jewellery Accounting, Trial Balance & GST Financial Statement Software', 'Live Balance Sheets, Metal-Aware P&L & 100% Tax-Compliant Reporting', 'General accounting packages fail when handling changing bullion prices, dual metal-and-rupee balances, and complex jewellery GST rules. GoldMatrix\'s Financial Statement module automatically compiles real-time Trial Balances, Balance Sheets, Profit & Loss statements, Cash/Fund Flows, and Sales/Purchase registers directly from your daily counter billing and workshop vouchers. Audit-ready, CA-friendly, and 100% compliant with GSTR-1, GSTR-3B, E-Invoicing, and E-Way bills.', 'Real-time balance sheet, profit & loss statement, cash/fund flow, chart of accounts, and automated GST returns (GSTR-1, GSTR-3B, E-Invoicing).', '[\"Trial Balance, Balance Sheet & Profit Loss statements\",\"Cash Flow, Fund Flow & Chart of Accounts\",\"Tax Return (GSTR-1, GSTR-3B, E-Invoice, E-Way Bill)\",\"Sale Reports, Purchase Reports & Detailed Trial Balance\"]', 'Business Owners, Chartered Accountants, Tax Consultants & Auditors', 'Built for jewellery business owners, Chief Financial Officers, Chartered Accountants, and tax consultants who need audit-ready financial statements without manual spreadsheets.', '[{\"icon\":\"bi-calculator-fill\",\"title\":\"Trial Balance & Trial Balance Detailed Report\",\"desc\":\"Generate standard, periodic, and hierarchical trial balances with instant drill-down from primary account groups all the way to source transaction vouchers.\",\"points\":[\"Hierarchical group structure\",\"Drill-down to original voucher\",\"Opening, movement & closing balances\",\"Export to Excel & PDF for audit\"]},{\"icon\":\"bi-bank\",\"title\":\"Balance Sheet\",\"desc\":\"Live balance sheet reflecting inventory valuation at live or cost rates, liquid cash, bank accounts, customer receivables, and vendor liabilities.\",\"points\":[\"Schedule-III compliant format\",\"Stock asset valuation at market rate\",\"Debtor and creditor breakdown\",\"Multi-branch balance sheet consolidation\"]},{\"icon\":\"bi-graph-up-arrow\",\"title\":\"Profit Loss\",\"desc\":\"Comprehensive P&L reporting showing gross profit from metal, making charge margins, stone sales, and net profit after operating expenses.\",\"points\":[\"Metal trading margin vs making charge profit\",\"Operating expense categorization\",\"Monthly & quarterly comparative views\",\"Karat-wise gross margin breakdown\"]},{\"icon\":\"bi-water\",\"title\":\"Cash Flow & Fund Flow\",\"desc\":\"Track cash inflows and outflows across operating, investing, and financing activities to ensure healthy liquidity and working capital.\",\"points\":[\"Direct & indirect cash flow models\",\"Working capital tracking\",\"Monthly cash inflow\\/outflow forecast\",\"Liquidity health ratios\"]},{\"icon\":\"bi-diagram-2-fill\",\"title\":\"Chart Of Account\",\"desc\":\"Structure your financial accounts with customizable primary and secondary groups conforming to statutory jewellery accounting standards.\",\"points\":[\"Pre-configured jewellery account trees\",\"Custom ledger group creation\",\"Multi-currency ledger support\",\"Audit protection locks\"]},{\"icon\":\"bi-percent\",\"title\":\"Tax Return\",\"desc\":\"Auto-generate GSTR-1, GSTR-3B summaries ready for direct portal upload, along with built-in IRN e-invoicing and E-way bill generation.\",\"points\":[\"GSTR-1 & GSTR-3B JSON exports\",\"Direct NIC E-Invoice IRN API\",\"1-Click E-Way Bill generation\",\"Input Tax Credit (ITC) reconciliation\"]},{\"icon\":\"bi-receipt\",\"title\":\"Sale Reports & Purchase Reports\",\"desc\":\"Detailed registers of B2B and B2C sales and purchases filterable by HSN code, tax slab, branch, payment mode, and customer state.\",\"points\":[\"B2B vs B2C sales register\",\"HSN-wise tax summaries\",\"Purchase invoice register with ITC\",\"Branch and state-wise filtering\"]}]', 'Real-Time Financial Statements & Automated Tax Return Dashboard', 'Visual display showing live Balance Sheet, Trial Balance drill-down, and GST return portal-ready JSON export summaries.', '[\"Live stock valuation reflects on your balance sheet automatically\",\"Direct JSON export for GSTR-1 and GSTR-3B saves your CA dozens of hours\",\"Full audit trail logs every voucher creation, edit, and cancellation\"]', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"Does the Balance Sheet update automatically when gold rates change?\",\"a\":\"Yes. GoldMatrix supports both historical cost and live replacement valuation, reflecting current inventory asset value accurately on your balance sheet.\"},{\"q\":\"Can we export GSTR-1 and GSTR-3B data for direct government portal filing?\",\"a\":\"Yes. GoldMatrix generates portal-ready JSON files and Excel summaries for GSTR-1, GSTR-3B, and HSN-wise tax reports.\"},{\"q\":\"Can our external Chartered Accountant access our financial statements securely?\",\"a\":\"Yes. You can grant read-only auditor access with permissions restricted solely to financial statements, ledgers, and tax reports.\"},{\"q\":\"Does the system support E-Invoicing (IRN) and E-Way bill generation?\",\"a\":\"Yes. GoldMatrix integrates directly with the government GST portal to generate IRN QR codes and E-Way bills directly from the invoice screen.\"}]', '[\"operations\",\"report-analysis\",\"dashboard-live-rates\"]', 'Jewellery Accounting, Trial Balance & GST Financial Statement Software | GoldMatrix ERP', 'General accounting packages fail when handling changing bullion prices, dual metal-and-rupee balances, and complex jewellery GST rules. GoldMatrix\'s Financial S', 'financial statement, jewellery erp software, gold software, jewelry business system', '/features/financial-statement');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('7', 'Report Analysis', 'report-analysis', NULL, NULL, 'bi-bar-chart-line', NULL, NULL, 'published', '7', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'BUSINESS INTELLIGENCE', 'Deep BI & Analytics', 'Jewellery Business Intelligence & Report Analysis Software', '100+ Deep Reports: Transactions, Ageing, Karatwise P&L & Audit Trails', 'Jewellery Business Intelligence & Report Analysis Software', '100+ Deep Reports: Transactions, Ageing, Karatwise P&L & Audit Trails', 'You can\'t grow what you don\'t measure. GoldMatrix\'s Report Analysis module delivers 100+ actionable business intelligence reports covering every corner of your jewellery enterprise. From daily transaction registers and debtor ageing buckets to customer KYC history, Karatwise P&L breakdown, gold fixing positions, and physical barcode scan audit logs — give your leadership the exact data needed to increase profitability and eliminate inventory shrinkage.', '100+ deep reports including transaction ledgers, customer KYC & ageing, Karatwise P&L, reward point balances, and barcode scan discrepancy logs.', '[\"Transactions, Ledger, Day & Ageing reports\",\"Customer \\/ KYC & Ledger Balance reports\",\"Fixing Position & Karatwise Profit & Loss\",\"Reward Point & Barcode Scan discrepancy reports\"]', 'Jewellery Enterprise Owners, Store Directors, Bullion Traders & Auditors', 'Built for jewellery enterprise owners, store managers, bullion traders, and inventory auditors who require deep, granular visibility to optimize stock turn and cash flow.', '[{\"icon\":\"bi-receipt\",\"title\":\"Transactions Report & Day Report\",\"desc\":\"Detailed register of all sales, purchases, estimates, returns, and counter adjustments filterable by date, branch, salesperson, and payment mode.\",\"points\":[\"Daily transaction register\",\"Payment mode breakdown\",\"Cancelled & void bill register\",\"Estimate-to-bill conversion stats\"]},{\"icon\":\"bi-journal-text\",\"title\":\"Account Ledger Report & Ledger Balance Report\",\"desc\":\"Party-wise statement showing running balances in both currency and fine gold weight with 1-click WhatsApp and PDF export.\",\"points\":[\"Dual pure gold & cash ledger statement\",\"Summary of all debtor\\/creditor balances\",\"1-Click WhatsApp statement dispatch\",\"Multi-branch balance compilation\"]},{\"icon\":\"bi-clock-history\",\"title\":\"Ageing Report\",\"desc\":\"Identify overdue customer and vendor balances with 30\\/60\\/90\\/120+ day aging buckets and automatic payment reminder triggers.\",\"points\":[\"Aging bucket reports (30-120+ days)\",\"High-risk debtor alerts\",\"Automated payment reminder messages\",\"Credit limit compliance tracking\"]},{\"icon\":\"bi-person-vcard\",\"title\":\"Customer \\/ KYC Report\",\"desc\":\"Comprehensive customer database tracking purchase frequency, lifetime value (LTV), government KYC compliance (PAN\\/Aadhaar\\/ID), and birthdays\\/anniversaries.\",\"points\":[\"KYC compliance register\",\"High-value customer ranking (RFM)\",\"Special date reminder lists\",\"Customer preference analysis\"]},{\"icon\":\"bi-shield-exclamation\",\"title\":\"Fixing Position\",\"desc\":\"Monitor open bullion rate-fix contracts, unpriced metal receipts, and hedging exposure to protect against sudden market price swings.\",\"points\":[\"Net unhedged gold weight position\",\"Bullion contract rate fixing ledger\",\"Rate fluctuation risk analysis\",\"Live market valuation exposure\"]},{\"icon\":\"bi-gem\",\"title\":\"Karatwise Profit & Loss\",\"desc\":\"Deep profitability breakdown across 24K, 22K, 18K, 14K, 9K gold, platinum, and diamond categories to discover high-margin product lines.\",\"points\":[\"Purity-wise gross margin\",\"Category profitability ranking\",\"Slow-moving metal analysis\",\"Making charge yield per karat\"]},{\"icon\":\"bi-award-fill\",\"title\":\"Reward Point Report\",\"desc\":\"Track customer loyalty point accruals, kitty scheme installment collections, maturity dates, and bonus redemption statistics.\",\"points\":[\"Active kitty scheme balances\",\"Overdue installment reports\",\"Reward points liability statement\",\"Scheme redemption ROI analytics\"]},{\"icon\":\"bi-upc-scan\",\"title\":\"Barcode Scan Report\",\"desc\":\"Compare physical stock scan counts against system records to identify missing items, misplaced trays, or unaccounted shrinkage.\",\"points\":[\"Physical vs system variance logs\",\"Misplaced tray identification\",\"Missing item audit register\",\"Auditor sign-off reports\"]}]', 'Analytics Command Center: Karatwise P&L & Stock Scan Variance', 'Visual representation of the Report Analysis dashboard showing Karatwise P&L graphical charts and the physical Barcode Scan discrepancy report.', '[\"Karatwise gross profit charts split across 24K, 22K, 18K, and Diamond lines\",\"Physical stock scan audit report highlighting matched, missing, and extra items\",\"Export any report to Excel, PDF, or CSV with 1 click\"]', 'https://images.unsplash.com/photo-1605100804763-247f67b3557e?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"Can reports be exported to Excel, PDF, or CSV?\",\"a\":\"Yes. Every report in GoldMatrix can be exported with 1 click to Excel, PDF, or CSV format with custom date filters and column arrangements.\"},{\"q\":\"What is the Fixing Position report used for?\",\"a\":\"It tracks your net open gold weight position (unhedged gold bought vs sold), protecting bullion traders and jewelers from adverse market fluctuations.\"},{\"q\":\"How does the Barcode Scan discrepancy report work?\",\"a\":\"You scan physical showroom trays using a handheld barcode\\/RFID reader; the system instantly compares scanned tags against book stock, flagging missing or misplaced pieces.\"},{\"q\":\"Can we schedule automated daily summary reports to our mobile phone?\",\"a\":\"Yes. GoldMatrix can automatically dispatch daily executive closing summaries and sales digests directly to your WhatsApp or email every evening.\"}]', '[\"financial-statement\",\"stock-management\",\"dashboard-live-rates\"]', 'Jewellery Business Intelligence & Report Analysis Software | GoldMatrix ERP', 'You can\'t grow what you don\'t measure. GoldMatrix\'s Report Analysis module delivers 100+ actionable business intelligence reports covering every corner of your ', 'report analysis, jewellery erp software, gold software, jewelry business system', '/features/report-analysis');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('8', 'Employee Management', 'employee-management', NULL, NULL, 'bi-people', NULL, NULL, 'published', '8', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'WORKFORCE & SECURITY', 'HR & Staff Control', 'Jewellery Staff Attendance, Incentive Math & Inventory Assignment Software', 'Motivate Sales Staff, Automate Payroll & Secure Showcase Inventory', 'Jewellery Staff Attendance, Incentive Math & Inventory Assignment Software', 'Motivate Sales Staff, Automate Payroll & Secure Showcase Inventory', 'Managing showroom sales teams, cashiers, and workshop staff requires both performance incentives and strict inventory accountability. GoldMatrix\'s Employee Management module combines HR automation with jewellery-specific security. Track biometric attendance, calculate sales commissions on making charges, process monthly salaries and advances, and assign specific showcase inventory trays to sales associates with morning checkout and evening check-in audits.', 'Manage staff attendance, calculate sales commissions and incentives, generate payroll, and assign/unassign showroom inventory to sales staff with full accountability.', '[\"Employee Dashboard, Attendance & Attendance Report\",\"Employee Advance, Advance Request & Incentive math\",\"Employee Reports, Salary & Digital Pay Slips\",\"Assign \\/ UnAssign Inventory To Sales Team with item logs\"]', 'Multi-Counter Jewellery Showrooms, Retail Chains & HR Managers', 'Built for multi-counter jewellery showrooms, retail chains, and workshop managers who want to motivate high-performing staff while securing high-value showcase inventory.', '[{\"icon\":\"bi-speedometer2\",\"title\":\"Employee Dashboard\",\"desc\":\"Live salesperson leaderboard tracking daily sales, conversion rates, average ticket size, and monthly target achievements.\",\"points\":[\"Real-time showroom leaderboard\",\"Conversion rate & footfall stats\",\"Average billing value per staff\",\"Monthly star performer badge\"]},{\"icon\":\"bi-fingerprint\",\"title\":\"Employee Attendance & Attendance Report\",\"desc\":\"Biometric hardware sync (fingerprint\\/face) and mobile geolocation check-in with automated late-mark and overtime tracking.\",\"points\":[\"Biometric hardware device sync\",\"Multi-shift scheduling\",\"Overtime & late-mark rules\",\"Detailed monthly attendance reports\"]},{\"icon\":\"bi-cash-coin\",\"title\":\"Employee Advance & Advance Request\",\"desc\":\"Manage staff loan applications, salary advances, and automated monthly installment deductions from payroll.\",\"points\":[\"Staff advance request portal\",\"Owner approval workflow\",\"Automated payroll deduction\",\"Staff loan balance ledger\"]},{\"icon\":\"bi-percent\",\"title\":\"Employee Incentive\",\"desc\":\"Automate complex jewellery commissions based on making charge percentages, flat amount per gram sold, or target tier bonuses.\",\"points\":[\"Making charge margin-based bonus\",\"Rupees-per-gram commission rules\",\"Tiered milestone bonuses\",\"Monthly commission pay slip\"]},{\"icon\":\"bi-cash-stack\",\"title\":\"Employee Salary & Employee Reports\",\"desc\":\"1-Click monthly payroll calculation factoring in attendance, incentives, advances, and taxes with printable digital salary slips.\",\"points\":[\"1-Click monthly payroll processing\",\"Staff advance deduction\",\"Digital salary slip generation\",\"Bank salary transfer sheet export\"]},{\"icon\":\"bi-boxes\",\"title\":\"Assign Inventory To Sales Team\",\"desc\":\"Assign showcase trays to specific sales staff at store opening and verify 100% item return at store closing.\",\"points\":[\"Morning showcase tray assignment\",\"Evening hand-back audit scan\",\"Salesperson stock custody log\",\"Missing piece liability attribution\"]},{\"icon\":\"bi-box-arrow-right\",\"title\":\"Assign Inventory & UnAssign Inventory\",\"desc\":\"Quickly transfer or release custody of jewellery pieces between counters and salespersons during busy showroom hours.\",\"points\":[\"Counter-to-counter handover log\",\"Manager sign-off on transfers\",\"Instant custody update\",\"Zero untracked showcase pieces\"]},{\"icon\":\"bi-tag-fill\",\"title\":\"Assign Inventory Items\",\"desc\":\"Item-level accountability ensuring any missing showcase piece is instantly attributed to the responsible counter staff member.\",\"points\":[\"Individual barcode item custody\",\"High-value solitaire assignment\",\"Audit scan verification\",\"Complete staff action audit trail\"]}]', 'Showroom Staff Accountability & Commission Dashboard', 'Visual display showing the Assign Inventory to Sales Team interface with tray checkout/check-in logs, alongside the Salesperson Commission Calculation dashboard.', '[\"Showcase tray custody assigned to individual sales associates\",\"Commission calculation linked directly to making charges earned\",\"Biometric attendance sync and 1-click digital pay slip generation\"]', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"How does the showcase inventory assignment protect against counter theft?\",\"a\":\"Sales associates scan assigned trays into their personal custody at morning opening. At closing, a return scan verifies all pieces are accounted for before staff depart.\"},{\"q\":\"Can commission be calculated on making charges instead of gross sale value?\",\"a\":\"Yes. GoldMatrix supports flexible commission rules including % on making charges, fixed rupees per gram, or target milestone bonuses.\"},{\"q\":\"Does it connect directly with biometric fingerprint\\/face attendance machines?\",\"a\":\"Yes. GoldMatrix syncs with major biometric attendance devices (eSSL, ZKTeco, Realtime) to pull shift attendance automatically.\"},{\"q\":\"Can staff request salary advances through the system?\",\"a\":\"Yes. Employees or managers can submit advance requests, which upon owner approval are logged in the employee ledger and deducted from monthly payroll.\"}]', '[\"stock-management\",\"settings-admin\",\"dashboard-live-rates\"]', 'Jewellery Staff Attendance, Incentive Math & Inventory Assignment Software | GoldMatrix ERP', 'Managing showroom sales teams, cashiers, and workshop staff requires both performance incentives and strict inventory accountability. GoldMatrix\'s Employee Mana', 'employee management, jewellery erp software, gold software, jewelry business system', '/features/employee-management');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('9', 'Stock Management', 'stock-management', NULL, NULL, 'bi-box-seam', NULL, NULL, 'published', '9', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'ENTERPRISE INVENTORY ENGINE', 'Inventory & Stock Control', 'Jewellery Inventory Management, RFID & Consignment Software', 'Complete Control Across 4 Sub-Groups: Catalogue, Consignment, Precious Metals & RFID', 'Jewellery Inventory Management, RFID & Consignment Software', 'Complete Control Across 4 Sub-Groups: Catalogue, Consignment, Precious Metals & RFID', 'Jewellery inventory represents your largest capital investment and your highest operational risk. GoldMatrix\'s Stock Management module is the industry\'s most comprehensive inventory engine, structured across 4 specialized sub-groups: Digital Catalogue & Barcode Re-printing, Consignments (Memo In/Out) & Branch Transfers, Gold/Platinum/Diamond Vaults, and Imitation/Watches with UHF RFID Automation. Track every milligram of precious metal and every carat of certified diamond with 100% precision.', 'The largest jewellery inventory module covering Product Catalogue, Barcodes, Consignment & Memos, Branch Transfers, Gold/Platinum/Diamond vaults, Imitation, and RFID auditing.', '[\"Catalogue & Stock: Product Catalogue & Barcode Re-Print\",\"Consignment & Transfer: Memo In\\/Out & Branch Transfers\",\"Gold, Platinum & Diamond: Category-wise precious inventory\",\"Imitation, Services & Reports: Watches, RFID & Valuation\"]', 'Inventory Controllers, Showroom Managers, Stock Auditors & Multi-Branch Chains', 'Built for inventory controllers, showroom managers, stock auditors, and multi-branch jewellery chain operators who need 100% tamper-proof inventory accuracy.', '[]', '4-Subgroup Inventory Architecture & UHF RFID Bulk Scanning', 'Visual display showing the 4 interactive inventory sub-tabs (Catalogue & Stock, Consignment & Transfer, Gold/Platinum/Diamond, Imitation/Services/Reports) with RFID tray scan verification.', '[\"UHF RFID tray scanning verifies 50 items in 3 seconds\",\"Consignment Memo In \\/ Memo Out approval tracking with 1-click billing\",\"Multi-valuation engine computes exact inventory worth at purchase cost and live replacement value\"]', 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"How fast is RFID tray inventory scanning in GoldMatrix?\",\"a\":\"You can scan an entire showcase tray containing 50+ tagged jewellery items in under 3 seconds, turning a 4-hour physical audit into a 5-minute task.\"},{\"q\":\"How does Memo Out (approval) work for VIP customers?\",\"a\":\"You generate an approval slip with photos and weights. If the customer keeps 2 items and returns 1, GoldMatrix auto-bills the 2 items and returns the 3rd to stock in 1 click.\"},{\"q\":\"Can we track certified diamonds with GIA\\/IGI certificate numbers?\",\"a\":\"Yes. You can record 4Cs parameters, certificate numbers, carat weights, and per-carat pricing with automatic stone weight deduction during counter billing.\"},{\"q\":\"Does the system alert us to dead or slow-moving stock?\",\"a\":\"Yes. The Inventory Valuation report highlights items sitting in stock beyond your defined holding threshold so you can melt, remodel, or discount them.\"}]', '[\"order-management\",\"production\",\"operations\"]', 'Jewellery Inventory Management, RFID & Consignment Software | GoldMatrix ERP', 'Jewellery inventory represents your largest capital investment and your highest operational risk. GoldMatrix\'s Stock Management module is the industry\'s most co', 'stock management, jewellery erp software, gold software, jewelry business system', '/features/stock-management');
INSERT INTO `erp_modules` (`id`, `name`, `slug`, `short_description`, `full_description`, `icon`, `featured_image_id`, `benefits`, `status`, `display_order`, `created_at`, `updated_at`, `badge`, `category`, `h1`, `h2`, `headline`, `subtitle`, `intro`, `description`, `bullets`, `target_persona`, `persona_desc`, `sub_features`, `visual_title`, `visual_desc`, `visual_points`, `visual_image`, `faqs`, `related`, `meta_title`, `meta_desc`, `meta_keywords`, `canonical_url`) VALUES ('10', 'Settings & Admin', 'settings-admin', NULL, NULL, 'bi-gear-wide-connected', NULL, NULL, 'published', '10', '2026-09-07 20:08:33', '2026-09-07 20:08:33', 'ENTERPRISE SECURITY & CONFIG', 'Administration', 'Jewellery ERP Administration, User Roles, Voucher Types & CRM Software', 'Enterprise Security, Custom Voucher Numbering, Activity Logs & WhatsApp CRM', 'Jewellery ERP Administration, User Roles, Voucher Types & CRM Software', 'Enterprise Security, Custom Voucher Numbering, Activity Logs & WhatsApp CRM', 'Enterprise jewellery software must adapt to your company\'s hierarchy, security standards, and customer communication channels. GoldMatrix\'s Settings & Admin module provides complete administrative control. Configure custom voucher types with branch-specific prefixes, enforce granular role-based permissions, monitor an immutable real-time activity log for forensic auditability, and set up automated WhatsApp CRM rules for customer birthday greetings, scheme reminders, and rate updates.', 'Custom voucher types, user management with role-based permissions, live activity logs, WhatsApp CRM configuration, and software customization.', '[\"Set Software: Company, branch & fiscal configuration\",\"Voucher Type: Custom voucher prefixes & numbering\",\"User Management: Granular role-based permissions\",\"Activity Log: Forensic audit trail & WhatsApp CRM\"]', 'Enterprise Owners, IT Directors & Showroom System Administrators', 'Built for enterprise owners, IT directors, and system administrators who require bank-grade access security, customized voucher numbering, and automated customer marketing.', '[{\"icon\":\"bi-laptop\",\"title\":\"Set Software\",\"desc\":\"Configure company details, multiple branch entities, fiscal calendars, currency symbols, and default gold\\/silver purity standards.\",\"points\":[\"Multi-branch entity configuration\",\"Fiscal calendar settings\",\"Purity standard definitions\",\"Branding & logo setup\"]},{\"icon\":\"bi-file-earmark-ruled\",\"title\":\"Voucher Type\",\"desc\":\"Create custom voucher series for retail tax invoices, wholesale bills, estimate slips, repair receipts, and jobwork with custom prefix numbering.\",\"points\":[\"Branch-specific voucher prefixes\",\"Automatic sequential numbering\",\"Custom voucher layout mapping\",\"Separate tax & estimate series\"]},{\"icon\":\"bi-person-gear\",\"title\":\"User Management\",\"desc\":\"Define granular roles (Director, Store Manager, Cashier, Accountant, Karigar Head) with button-level read, write, edit, and delete permissions.\",\"points\":[\"Granular module permissions\",\"Manager OTP approval rules\",\"Session timeout & multi-device control\",\"Biometric login support\"]},{\"icon\":\"bi-shield-check\",\"title\":\"Activity Log\",\"desc\":\"Immutable security log recording every user action, IP address, timestamp, old value, and new value for 100% internal fraud prevention.\",\"points\":[\"IP address & timestamp tracking\",\"Before & after value comparison\",\"Bill modification \\/ deletion alerts\",\"Exportable audit logs for compliance\"]},{\"icon\":\"bi-whatsapp\",\"title\":\"CRM\",\"desc\":\"Set up automated WhatsApp and SMS triggers for customer birthday wishes, anniversary offers, kitty scheme due dates, and live rate alerts.\",\"points\":[\"WhatsApp Business API integration\",\"Automated birthday & anniversary triggers\",\"Payment reminder templates\",\"Promotional campaign broadcast\"]}]', 'Role Permission Matrix & Immutable Activity Audit Log', 'Visual display showing the User Role Permission Matrix with granular button-level access checkboxes, alongside the Live Activity Log tracking user edits with timestamps.', '[\"Button-level user permissions prevent unauthorized discounts and data export\",\"Immutable activity log records forensic before-and-after values with timestamps\",\"Automated WhatsApp CRM workflows engage customers and boost repeat store visits\"]', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?w=900&auto=format&fit=crop&q=80', '[{\"q\":\"Can we customize invoice numbering prefixes for each branch showroom?\",\"a\":\"Yes. You can create independent voucher numbering series with custom prefixes (e.g. DXB-INV-2026-0001, MUM-RET-2026-0001) for each branch.\"},{\"q\":\"How does the Activity Log prevent employee fraud?\",\"a\":\"The immutable activity log records every critical action — bill cancellations, discount overrides, backdated entries, and stock adjustments — with the staff member\'s name, IP, and timestamp.\"},{\"q\":\"How does the WhatsApp CRM automation work?\",\"a\":\"GoldMatrix connects with the WhatsApp Business API to automatically send transactional bills, payment receipts, order ready alerts, and promotional greetings on customer birthdays.\"},{\"q\":\"Can we restrict cashiers from giving discounts without manager approval?\",\"a\":\"Yes. You can configure permission rules requiring a manager OTP or biometric authorization whenever a cashier attempts to apply a discount above a set limit.\"}]', '[\"employee-management\",\"dashboard-live-rates\",\"operations\"]', 'Jewellery ERP Administration, User Roles, Voucher Types & CRM Software | GoldMatrix ERP', 'Enterprise jewellery software must adapt to your company\'s hierarchy, security standards, and customer communication channels. GoldMatrix\'s Settings & Admin mod', 'settings & admin, jewellery erp software, gold software, jewelry business system', '/features/settings-admin');
