INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('2', 'hero_slides', 'Jewellery POS Software for Modern Retail Showrooms.', '', 'High-speed billing, barcode scanning, old gold exchange, advance booking, and automated GST invoices in seconds.', '', '', '/uploads/homepage/hp_6a91bc71f2209.png', '2', '1', '2026-08-28 16:46:15', 'RETAIL & SHOWROOM POS', '', '/uploads/homepage/hp_6a91bc7203732.png', 'Jewellery POS Software Showcase', 'Explore POS Features', '/features', '', '', '[\"Fast Billing\",\"Old Gold Exchange\",\"Barcode & RFID\",\"GST Invoices\"]', '#F59E0B');
