INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('8', 'feature_showcase', 'Transaction report', 'Gain Complete Financial Clarity', 'The Transaction Report ensures transparent and detailed tracking of all financial activities within your jewelry business. From purchases and sales to returns and adjustments, this report provides an organized view of every transaction, enabling better financial management and decision-making.', 'bi-bar-chart-fill', '', '/uploads/homepage/hp_6a91f411ea15d.png', '1', '1', '2026-08-28 20:40:25', '', '', '', 'Transaction report Dashboard', '', '#contact', '', '', '[]', '#dc9423');
INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('9', 'feature_showcase', 'Marketing Integrations', 'Connect, Automate, and Grow', 'Seamlessly integrate your business with leading marketing platforms to streamline promotions and customer engagement. From campaign tracking to performance insights, Marketing Integrations help you automate outreach, analyze results, and optimize strategies.', 'bi-person-fill', '', '/uploads/homepage/hp_6a91f963256ae.png', '2', '1', '2026-08-28 20:40:25', '', '', '', 'Marketing Integrations Dashboard', '', '#contact', '', '', '[]', '#8b5cf6');
INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('10', 'feature_showcase', 'Manufacturing Dashboard', 'Manufacturing Dashboard', 'The Manufacturing Dashboard provides a comprehensive view of ongoing, delayed, and completed manufacturing jobs. Designed for efficient workflow management, it allows businesses to track progress, identify bottlenecks, and ensure timely order completion. Track jobs in progress, delayed, on hold, and yet to initiate.View the number of orders assigned to each workstation. Quickly identify and address overdue jobs.
INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('12', 'feature_spotlight', 'Retails & Showrooms', 'Simplify Jewellery Retail and Showroom Operations', 'GoldMatrix Jewellery Software is built to support the day-to-day operations of jewellery retail stores and showrooms. It helps businesses maintain control over stock, sales, and customer transactions while ensuring smooth and efficient store management.', '', '', '/uploads/homepage/hp_6a9207ee140eb.png', '1', '1', '2026-08-28 21:57:41', '', '', '', '', '', '', '', '', '[\"Track inventory in real time, including available, reserved, and pending items\",\"Maintain optimal stock levels using smart reorder alerts\",\"Automate routine processes for sales, purchases, and returns\",\"Generate barcodes and design custom price tags and labels effortlessly\"]', '#F59E0B');
INSERT INTO `homepage_items` (`id`, `section`, `title`, `subtitle`, `description`, `icon`, `link`, `image`, `sort_order`, `is_active`, `created_at`, `badge`, `extra`, `mobile_image`, `alt_text`, `btn1_text`, `btn1_link`, `btn2_text`, `btn2_link`, `features`, `accent_color`) VALUES ('13', 'feature_spotlight', 'Manufacturing', 'Improve Productivity with Jewellery Software', 'GoldMatrix Manufacturing Software is designed to support jewellery manufacturers by simplifying production management and improving operational control. It helps businesses plan, track, and optimize manufacturing activities while maintaining accuracy and cost efficiency.', '', '', '/uploads/homepage/hp_6a92088a510d9.png', '2', '1', '2026-08-28 21:57:41', '', '', '', '', '', '', '', '', '[\"Plan and manage production jobs with clear task assignments\",\"Support batch-based manufacturing for better efficiency\",\"Calculate accurate production costs and track finished goods sales\",\"Monitor work-in-progress inventory at every stage\"]', '#F59E0B');
