INSERT INTO `blog_categories` (`id`, `name`, `slug`, `description`, `color`, `created_at`, `updated_at`) VALUES ('5', 'Software Features', 'software-features', 'Deep dive into GoldMatrix ERP features', '#EF4444', '2026-08-31 07:02:54', '2026-08-31 07:02:54');
INSERT INTO `blog_categories` (`id`, `name`, `slug`, `description`, `color`, `created_at`, `updated_at`) VALUES ('6', 'Industry News', 'industry-news', 'Latest news from the jewellery industry', '#0EA5E9', '2026-08-31 07:02:54', '2026-08-31 07:02:54');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `category_id`, `author_name`, `status`, `meta_title`, `meta_description`, `views`, `published_at`, `created_at`, `updated_at`, `focus_keyword`, `alt_text`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `schema_type`, `tags`, `reading_time`) VALUES ('1', 'How GoldMatrix ERP Transformed a Mumbai Jewellery Showroom', 'goldmatrix-erp-transformed-mumbai-jewellery-showroom', 'A busy Mumbai showroom with 3 branches was struggling with stock discrepancies and GST filing chaos. Here is how GoldMatrix ERP solved their problems in 30 days.', '<h2>The Challenge</h2><p>Ravi Jewellers, a well-established showroom in Dadar, Mumbai, was dealing with daily headaches — wrong stock counts, duplicate billing, and a nightmare during GST filing month.</p><h2>The Solution</h2><p>After implementing GoldMatrix ERP, they achieved real-time inventory across all 3 branches, automated GST invoicing with e-invoice generation, karigar job tracking with zero manual errors, and daily closing reports in under 2 minutes.</p><h2>Results After 30 Days</h2><p>Stock accuracy improved to 99.8%. GST filing time reduced from 4 hours to 20 minutes. Staff productivity improved by 40%.</p>', '', '1', 'GoldMatrix Team', 'published', 'How GoldMatrix ERP Helped a Mumbai Jewellery Showroom | Case Study', 'Read how GoldMatrix ERP transformed a 3-branch Mumbai jewellery showroom with automated GST, real-time inventory, and karigar management.', '184', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '', '', '', 'index,follow', '', '', '', 'BlogPosting', '', '0');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `category_id`, `author_name`, `status`, `meta_title`, `meta_description`, `views`, `published_at`, `created_at`, `updated_at`, `focus_keyword`, `alt_text`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `schema_type`, `tags`, `reading_time`) VALUES ('2', 'Complete Guide to GST for Jewellers in India (2025)', 'complete-guide-gst-jewellers-india-2025', 'Everything jewellers need to know about GST — rates on gold, making charges, HUID, e-invoice, and how to stay fully compliant with zero penalties.', '<h2>GST Rates on Gold Jewellery</h2><p>As of 2025, gold jewellery attracts 3% GST on the value of gold, and 5% GST on making charges.</p><h2>HUID and Hallmarking</h2><p>All gold jewellery above 2 grams must carry BIS hallmark with a unique HUID. GoldMatrix ERP automatically records and prints HUID on every invoice.</p><h2>E-Invoice for Jewellers</h2><p>If your annual turnover exceeds Rs 5 crore, e-invoice is mandatory. GoldMatrix integrates with the GST portal to generate IRN and QR codes instantly.</p>', '', '2', 'GoldMatrix Team', 'published', 'Complete GST Guide for Jewellers India 2025 | GoldMatrix', 'Complete guide on GST rates, HUID, e-invoice and GST return filing for jewellers in India. Stay compliant with GoldMatrix ERP.', '133', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '', '', '', 'index,follow', '', '', '', 'BlogPosting', '', '0');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `category_id`, `author_name`, `status`, `meta_title`, `meta_description`, `views`, `published_at`, `created_at`, `updated_at`, `focus_keyword`, `alt_text`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `schema_type`, `tags`, `reading_time`) VALUES ('3', '7 Signs Your Jewellery Shop Needs an ERP Software Right Now', '7-signs-jewellery-shop-needs-erp-software', 'Is your jewellery business still running on manual registers or basic billing software? Here are 7 clear signs that you need a dedicated Jewellery ERP.', '<h2>1. Stock Discrepancies Every Month</h2><p>If your physical count never matches your software count, your inventory system cannot handle jewellery-specific units like grams, karats, and pieces simultaneously.</p><h2>2. GST Filing Takes Days</h2><p>If your accountant is manually matching invoices, this is a clear sign of missing automation.</p><h2>3. No Visibility Across Branches</h2><p>If you have to call each branch to know what stock they have, real-time multi-branch ERP is what you need.</p><h2>4. Karigar Records Are on Paper</h2><p>Paper-based karigar job cards cause disputes. ERP tracks every job with weight-in and weight-out.</p><h2>5. Customer Ledgers Are Manual</h2><p>Kitty schemes and outstanding payments managed on paper lead to errors and lost revenue.</p>', '', '4', 'GoldMatrix Team', 'published', '7 Signs Your Jewellery Shop Needs ERP Software | GoldMatrix', 'Discover 7 clear signs that your jewellery business needs a dedicated ERP software. From stock errors to GST chaos — GoldMatrix solves them all.', '203', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '', '', '', 'index,follow', '', '', '', 'BlogPosting', '', '0');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `featured_image`, `category_id`, `author_name`, `status`, `meta_title`, `meta_description`, `views`, `published_at`, `created_at`, `updated_at`, `focus_keyword`, `alt_text`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `schema_type`, `tags`, `reading_time`) VALUES ('4', 'RFID Jewellery Automation: The Future of Inventory Management', 'rfid-jewellery-automation-future-inventory', 'RFID technology is changing how jewellery showrooms track their stock. Learn how RFID-enabled ERP can reduce pilferage and provide real-time inventory.', '<h2>What is RFID in Jewellery?</h2><p>RFID (Radio Frequency Identification) tags are tiny chips attached to each jewellery piece. A scanner can read hundreds of items in seconds without line of sight.</p><h2>Benefits for Jewellery Showrooms</h2><p>Full inventory count in minutes, anti-theft alerts at exit points, instant item location on the showroom floor, and faster billing.</p><h2>GoldMatrix RFID Integration</h2><p>GoldMatrix ERP supports RFID scanners for automatic stock taking, customer-facing display of product details, and loss prevention alerts.</p>', '', '5', 'GoldMatrix Team', 'published', 'RFID Jewellery Automation & Inventory Management | GoldMatrix ERP', 'Learn how RFID technology combined with GoldMatrix ERP provides real-time jewellery inventory, anti-theft alerts, and faster billing.', '176', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '2026-08-31 07:04:05', '', '', '', 'index,follow', '', '', '', 'BlogPosting', '', '0');
